import{_ as r,C as e,o as a,c as i,j as d,a as s,E as o,a2 as n}from"./chunks/framework.DGvnA5EY.js";const k="/workbuddy-guide/assets/22-hei-skill.D5hoMjEB.png",_=JSON.parse('{"title":"第 22 章 打造 Skill：将书和视频蒸馏为可执行 Skill","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 你一定有过这种体验：收藏夹里躺着 100 篇干货，B 站收藏了 20 个教程视频， 真要干活的时候一条也想不起来用。收藏 ≠ 能力，看懂 ≠ 可执行。","frontmatter":{"title":"第 22 章 打造 Skill：将书和视频蒸馏为可执行 Skill"},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 22 章 打造 Skill：将书和视频蒸馏为可执行 Skill/index.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 22 章 打造 Skill：将书和视频蒸馏为可执行 Skill/index.md","lastUpdated":1791629861000}'),u={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 22 章 打造 Skill：将书和视频蒸馏为可执行 Skill/index.md"};function p(h,t,S,b,q,g){const l=e("Paywall");return a(),i("div",null,[t[0]||(t[0]=d("h1",{id:"第-22-章-打造-skill-将书和视频蒸馏为可执行-skill",tabindex:"-1"},[s("第 22 章 打造 Skill：将书和视频蒸馏为可执行 Skill "),d("a",{class:"header-anchor",href:"#第-22-章-打造-skill-将书和视频蒸馏为可执行-skill","aria-label":'Permalink to "第 22 章 打造 Skill：将书和视频蒸馏为可执行 Skill"'},"​")],-1)),t[1]||(t[1]=d("blockquote",null,[d("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),o(l,{part:"3",variant:"banner"}),t[2]||(t[2]=n('<p>你一定有过这种体验：收藏夹里躺着 100 篇干货，B 站收藏了 20 个教程视频， 真要干活的时候一条也想不起来用。<strong>收藏 ≠ 能力，看懂 ≠ 可执行</strong>。</p><p>WorkBuddy 的 Skill 机制给了这个问题一个漂亮的答案：把一本书、一套课程、 甚至你自己踩坑三年的经验，<strong>蒸馏成一个&quot;说到就触发、触发就按你的规矩办&quot;的 专属技能</strong>。这一章教你完整走一遍这条蒸馏流水线——它也是本篇最重要的一章。</p><p><img src="'+k+'" alt="一只小黑坐在书前，把书里的精华蒸馏进一个小瓶子" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解本章主题，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这个-skill-值不值得做" tabindex="-1">一、先想清楚：这个 Skill 值不值得做 <a class="header-anchor" href="#一、先想清楚-这个-skill-值不值得做" aria-label="Permalink to &quot;一、先想清楚：这个 Skill 值不值得做&quot;">​</a></h2><p>动手前先用五问定标。做 Skill 和做任务不同，多问自己两个&quot;复用性&quot;问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>反例（不值得做）</th><th>正例（值得做）</th></tr></thead><tbody><tr><td>目标</td><td>这个 Skill 替你做哪类活</td><td>&quot;帮我写东西&quot;（太泛）</td><td>&quot;按我的栏目结构拆解热点、产出公众号初稿&quot;</td></tr><tr><td>受众/口径</td><td>输出给谁看、什么语气</td><td>无固定口径</td><td>每周固定发公众号，要求口语化、有案例</td></tr><tr><td>材料</td><td>方法论从哪来</td><td>凭模型自带的通用知识</td><td>一本你认可的书 + 你 10 篇历史爆文的写法</td></tr><tr><td>触发</td><td>什么话应该唤起它</td><td>想不起来说什么</td><td>&quot;拆解这个热点&quot;&quot;按我的风格写初稿&quot;</td></tr><tr><td>验收</td><td>怎么判断 Skill 做成了</td><td>&quot;感觉还行&quot;</td><td>新开对话说一句触发词，3 次里 3 次按你的结构输出</td></tr></tbody></table><p><strong>判断标准一句话：如果这个活你以后每周都会干、且每次要求基本一致——就值得 做成 Skill；只干一次的活，直接写提示词就行，别过度工程。</strong></p><h2 id="二、先选对-skill-造技能需要的工具组合" tabindex="-1">二、先选对 Skill：造技能需要的工具组合 <a class="header-anchor" href="#二、先选对-skill-造技能需要的工具组合" aria-label="Permalink to &quot;二、先选对 Skill：造技能需要的工具组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill 名称</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>skill-creator</strong></td><td>创建/修改技能</td><td>主力工具：把方法论生成为标准 SKILL.md 结构</td><td>零代码，对话里就能完成</td></tr><tr><td><strong>find-skills</strong></td><td>找技能</td><td>先看看别人有没有做过类似的，避免重复造轮子</td><td>也能帮你检查自己写的技能描述</td></tr><tr><td><strong>写书类技能（如福帮手写书）</strong></td><td>长内容生产</td><td>蒸馏&quot;写书类&quot;方法论时参考其章节组织方式</td><td>属社区技能，按需安装</td></tr><tr><td><strong>内容工作台类技能</strong></td><td>内容生产流水线</td><td>参考成熟内容类 Skill 的结构（知识库/规则/模板分离）</td><td>适合作为&quot;抄结构&quot;的对象</td></tr><tr><td><strong>pdf / Markdown Converter</strong></td><td>材料解析</td><td>把书的 PDF/讲稿转成可分析的文本</td><td>转换 ≠ 蒸馏，转换只是第一步</td></tr><tr><td><strong>视频字幕类工具/技能</strong></td><td>视频课转文字</td><td>把教程视频的字幕或逐字稿抽出来当原料</td><td>有字幕用字幕，没字幕先转文字</td></tr></tbody></table><blockquote><p><strong>零成本提示</strong>：本节所有技能均免费。先用 find-skills 搜&quot;书名关键词 + 笔记/写作&quot;， 十有八九有人做过近似技能——参考它的结构，再写你自己的，比从零开始快一倍。</p></blockquote>',11)),o(l,{part:"3"}),t[3]||(t[3]=d("p",null,[d("em",null,"—— 以上试读到此为止。第三篇共 4 章，完整版（飞书文档）包含全部实操内容。——")],-1))])}const c=r(u,[["render",p]]);export{_ as __pageData,c as default};
